// LEAK: exception before close means connection never returned
Connection conn = pool.getConnection();
prepareStatement(conn, sql); // throws exception!
conn.close(); // never reached!

// FIX: try-with-resources guarantees close
try (Connection conn = pool.getConnection();
     PreparedStatement ps = conn.prepareStatement(sql)) {
    // even if exception occurs, both are closed
}

